import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const PRIMARY = '#EA580C';
const PRIMARY_LIGHT = '#FFF4EE';
const PRIMARY_TEXT = '#EA580C';

export type NavItem = {
  id: string;
  label: string;
  path: string;
  icon?: string;
};

export type NavGroup = {
  id: string;
  label: string;
  path: string;
  icon?: string;
  children?: NavItem[];
};

interface SidebarProps {
  features: NavGroup[];
  collapsed?: boolean;
  onToggle?: () => void;
  onNavigate?: (item: NavItem) => void;
}

const WeeraIcon: React.FC<{ size?: number }> = ({ size = 22 }) => (
  <img
    src="/images/app_icon_fg.png"
    width={size}
    height={size}
    alt="Weera logo"
    style={{ objectFit: 'contain', display: 'block' }}
  />
);

export const Sidebar: React.FC<SidebarProps> = ({
  features,
  collapsed = false,
  onToggle,
  onNavigate,
}) => {
  const navigate = useNavigate();
  const location = useLocation();

  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    users: true,
  });

  const width = collapsed ? 56 : 280;

  const handleClick = (item: NavItem) => {
    navigate(item.path);
    onNavigate?.(item);
  };

  const toggleGroup = (groupId: string) => {
    setOpenGroups(prev => ({
      ...prev,
      [groupId]: !prev[groupId],
    }));
  };

  const isPathActive = (path: string) => {
    return location.pathname === path;
  };

  return (
    <aside
      style={{
        width,
        minWidth: width,
        height: '100vh',
        background: '#F9FBFC',
        borderRight: '1px solid #E1E4EA',
        boxSizing: 'border-box',
        padding: collapsed ? '12px 8px' : '12px 16px 12px 12px',
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        transition:
          'width 0.25s ease, min-width 0.25s ease, padding 0.25s ease',
        overflow: 'hidden',
        position: 'fixed',
        top: 0,
        left: 0,
        zIndex: 100,
      }}
    >
      {/* Header */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: collapsed ? 'center' : 'space-between',
          gap: 8,
          padding: '4px 4px 0',
        }}
      >
        {!collapsed && (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 8,
              whiteSpace: 'nowrap',
            }}
          >
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 8,
                background: PRIMARY,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                flexShrink: 0,
                boxShadow: `0 2px 8px ${PRIMARY}55`,
              }}
            >
              <WeeraIcon size={28} />
            </div>

            <span
              style={{
                fontSize: 15,
                fontWeight: 700,
                color: '#0f172a',
                letterSpacing: '0.02em',
              }}
            >
              WEERA
            </span>
          </div>
        )}

        {collapsed && (
          <div
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              background: PRIMARY,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              flexShrink: 0,
              marginBottom: 4,
              boxShadow: `0 2px 8px ${PRIMARY}55`,
            }}
          >
            <WeeraIcon size={28} />
          </div>
        )}

        <button
          onClick={onToggle}
          aria-label="Toggle sidebar"
          style={{
            background: 'none',
            border: '1px solid #E1E4EA',
            borderRadius: 8,
            cursor: 'pointer',
            padding: '6px 8px',
            display: 'flex',
            flexDirection: 'column',
            gap: 4,
            alignItems: 'center',
            flexShrink: 0,
          }}
        >
          <span
            style={{
              display: 'block',
              width: 16,
              height: 2,
              background: '#4B5565',
              borderRadius: 2,
            }}
          />

          <span
            style={{
              display: 'block',
              width: 16,
              height: 2,
              background: '#4B5565',
              borderRadius: 2,
            }}
          />

          <span
            style={{
              display: 'block',
              width: 16,
              height: 2,
              background: '#4B5565',
              borderRadius: 2,
            }}
          />
        </button>
      </div>

      {/* Navigation */}
      <nav style={{ flex: 1 }}>
        <ul
          style={{
            listStyle: 'none',
            padding: 0,
            margin: 0,
            display: 'flex',
            flexDirection: 'column',
            gap: 6,
          }}
        >
          {features.map(group => {
            const groupActive = isPathActive(group.path);
            const hasChildren = !!group.children?.length;
            const isOpen = openGroups[group.id];

            return (
              <React.Fragment key={group.id}>
                {/* Parent */}
                <li>
                  <button
                    onClick={() => {
                      if (hasChildren) {
                        toggleGroup(group.id);
                      } else {
                        handleClick({
                          id: group.id,
                          label: group.label,
                          path: group.path,
                          icon: group.icon,
                        });
                      }
                    }}
                    title={collapsed ? group.label : undefined}
                    style={{
                      width: '100%',
                      background: groupActive
                        ? PRIMARY_LIGHT
                        : 'transparent',
                      border: 'none',
                      borderRadius: 10,
                      cursor: 'pointer',
                      color: groupActive ? PRIMARY_TEXT : '#4B5565',
                      fontWeight: groupActive ? 600 : 500,
                      fontSize: 14,
                      display: 'flex',
                      alignItems: 'center',
                      // justifyContent: 'space-between',
                      padding: '10px 12px',
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      transition:
                        'background 0.15s ease, color 0.15s ease',
                      textAlign: 'left',
                      borderLeft: groupActive
                        ? `3px solid ${PRIMARY}`
                        : '3px solid transparent',
                    }}
                  >
                    <div
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 10,
                      }}
                    >
                      <span style={{ fontSize: 16, flexShrink: 0 }}>
                        {group.icon}
                      </span>

                      {!collapsed && <span>{group.label}</span>}
                    </div>
                  </button>
                </li>

                {/* Children */}
                {hasChildren &&
                  isOpen &&
                  group.children?.map(child => {
                    const childActive = isPathActive(child.path);

                    return (
                      <li
                        key={child.id}
                        style={{
                          paddingLeft: collapsed ? 0 : 18,
                        }}
                      >
                        <button
                          onClick={() => handleClick(child)}
                          title={collapsed ? child.label : undefined}
                          style={{
                            width: '100%',
                            background: childActive
                              ? PRIMARY_LIGHT
                              : 'transparent',
                            border: 'none',
                            borderRadius: 8,
                            cursor: 'pointer',
                            color: childActive
                              ? PRIMARY_TEXT
                              : '#6B7280',
                            fontWeight: childActive ? 600 : 400,
                            fontSize: 13,
                            display: 'flex',
                            alignItems: 'center',
                            gap: 10,
                            padding: '8px 10px',
                            whiteSpace: 'nowrap',
                            overflow: 'hidden',
                            transition:
                              'background 0.15s ease, color 0.15s ease',
                            textAlign: 'left',
                            borderLeft: childActive
                              ? `3px solid ${PRIMARY}`
                              : '3px solid transparent',
                          }}
                        >
                          <span style={{ fontSize: 15, flexShrink: 0 }}>
                            {child.icon}
                          </span>

                          {!collapsed && <span>{child.label}</span>}
                        </button>
                      </li>
                    );
                  })}
              </React.Fragment>
            );
          })}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
